import{C as e,S as t}from"./index-Biy-mziq.js";import{t as n}from"./firma-KGYe62Rc.js";var r={"[OPERATOR PŁATNOŚCI]":`operator_nazwa`,"[ADRES OPERATORA]":`operator_adres`,"[BLIK, Przelewy24, karta płatnicza]":`metody`,"[24]":`przelozenie_h`,"[DATA WEJŚCIA W ŻYCIE]":`data_od`,"[DOSTAWCA POCZTY]":`poczta`,"[NAZWA, np. MailerLite]":`newsletter`,"[NAZWA]":`biuro`};function i(e,t={}){if(e==null)return e;let n=String(e);for(let[e,i]of Object.entries(r))t[i]&&(n=n.split(e).join(t[i]));return n}var a={operator_nazwa:`PayU S.A.`,operator_adres:`ul. Grunwaldzka 186, 60-166 Poznań`},o=e=>e?new Date(e+`T12:00:00`).toLocaleDateString(`pl-PL`,{day:`numeric`,month:`long`,year:`numeric`}):null,s={title:`Regulamin serwisu i sklepu exmortis.pl`,sections:[{id:`p1`,title:`§1. Sprzedawca i kontakt`,body:[`1. Serwis exmortis.pl (dalej: „Serwis”) prowadzi [IMIĘ I NAZWISKO], przedsiębiorca prowadzący działalność gospodarczą pod firmą [NAZWA FIRMY], wpisany do Centralnej Ewidencji i Informacji o Działalności Gospodarczej, NIP [NIP], REGON [REGON], adres do doręczeń wpisany do CEIDG: [ADRES DO KORESPONDENCJI] (dalej: „Sprzedawca”).`,`2. Kontakt: e-mail [E-MAIL KONTAKTOWY], telefon [TELEFON] (opłata według taryfy operatora), formularz na stronie Kontakt, poczta: [ADRES DO KORESPONDENCJI]. Ten sam adres służy do składania reklamacji i oświadczeń o odstąpieniu od umowy.`,`3. Regulamin określa zasady korzystania z Serwisu, Konta i usług bezpłatnych, zakupu treści cyfrowych i kart podarunkowych, sesji 1:1, programu POWRÓT i udziału w Wydarzeniach. Jest regulaminem w rozumieniu ustawy o świadczeniu usług drogą elektroniczną.`,`4. Regulamin jest dostępny bezpłatnie pod adresem exmortis.pl/regulamin w sposób umożliwiający jego pobranie, utrwalenie i wydrukowanie. Wcześniejsze wersje są dostępne na tej stronie w części „Poprzednie wersje”.`]},{id:`p2`,title:`§2. Definicje`,body:[`1. Klient — osoba fizyczna, osoba prawna lub jednostka organizacyjna, która korzysta z Serwisu lub zawiera umowę ze Sprzedawcą.`,`2. Konsument — Klient będący osobą fizyczną, zawierający umowę niezwiązaną bezpośrednio z jego działalnością gospodarczą lub zawodową.`,`3. Przedsiębiorca na prawach konsumenta (PNPK) — osoba fizyczna zawierająca umowę bezpośrednio związaną z jej działalnością gospodarczą, gdy z treści umowy wynika, że nie ma ona dla niej charakteru zawodowego (§19).`,`4. Konto — indywidualny panel Klienta w Serwisie.`,`5. Treści cyfrowe — pliki PDF, nagrania audio, filmy i kursy wideo udostępniane w Koncie lub e-mailem.`,`6. Karta podarunkowa — jednorazowy kod kwotowy do wykorzystania w Skarbcu (§13).`,`7. Sesja 1:1 — odpłatne spotkanie indywidualne, w szczególności „Rozmowa na progu”.`,`8. Program POWRÓT — wieloetapowy program mentoringowy zawierany po rozmowie kwalifikacyjnej.`,`9. Wydarzenie — spotkanie grupowe online lub stacjonarne (np. webinar, „Wieczór powrotu”), bezpłatne albo płatne.`,`10. Usługi bezpłatne — Konto, newsletter „Listy powrotu”, test „Która śmierć jest Twoja?”, Minutnik ciszy, Biblioteka, bezpłatne materiały, opinie oraz zapisy na bezpłatne Wydarzenia.`,`11. Skarbiec — część Serwisu z ofertą produktów i usług.`,`12. Zamówienie — oświadczenie woli Klienta zmierzające do zawarcia umowy o dostarczenie Treści cyfrowej lub Karty podarunkowej albo o świadczenie usługi.`]},{id:`p3`,title:`§3. Wymagania techniczne, funkcjonalność i kompatybilność`,body:[`1. Do korzystania z Serwisu potrzebne są: urządzenie z dostępem do internetu, aktualna wersja przeglądarki Chrome, Firefox, Safari lub Edge z włączoną obsługą JavaScript oraz aktywny adres e-mail.`,`2. Pliki PDF wymagają programu do ich odczytu. Nagrania audio można odtworzyć w przeglądarce albo pobrać. Filmy odtwarza się w przeglądarce po zalogowaniu; zalecane łącze to co najmniej 5 Mb/s. Wydarzenia i sesje online odbywają się przez Zoom (aplikacja albo przeglądarka).`,`3. Treści cyfrowe są chronione technicznie: pliki PDF zawierają oznaczenie licencji (adres e-mail kupującego, numer zamówienia, datę) i ukryte znaczniki, a filmy wyświetlają znak wodny z adresem e-mail. Film można odtwarzać na jednym urządzeniu naraz. Próba usunięcia znaku wodnego zatrzymuje odtwarzanie.`,`4. Korzystanie z internetu wiąże się z ryzykami (np. złośliwe oprogramowanie, phishing, przejęcie hasła). Sprzedawca nigdy nie prosi o podanie hasła e-mailem ani telefonicznie.`,`5. Zakazane jest dostarczanie treści o charakterze bezprawnym i podejmowanie działań zakłócających pracę Serwisu.`]},{id:`p4`,title:`§4. Charakter usług — ważne zastrzeżenie`,body:[`1. Usługi i treści exmortis mają charakter mentoringowy i rozwojowy. Nie są psychoterapią, leczeniem, diagnozą ani poradnictwem medycznym, psychologicznym, prawnym lub finansowym i nie zastępują pomocy specjalisty.`,`2. W kryzysie, przy myślach samobójczych albo zagrożeniu życia lub zdrowia należy niezwłocznie zadzwonić pod numer 112, 116 123 (Telefon Zaufania dla Dorosłych) lub 800 70 2222 (Centrum Wsparcia, bezpłatnie, całą dobę) albo skontaktować się z lekarzem.`,`3. Konto i usługi odpłatne są przeznaczone dla osób pełnoletnich.`]},{id:`p5`,title:`§5. Usługi bezpłatne`,body:[`1. Umowa o Usługę bezpłatną zostaje zawarta z chwilą rozpoczęcia korzystania z niej (np. wysłania formularza, otwarcia testu), na czas nieoznaczony, a przy usługach jednorazowych — na czas ich wykonania.`,`2. Newsletter „Listy powrotu” jest wysyłany po potwierdzeniu zapisu linkiem z e-maila. Wypisać się można w każdej chwili, bez kosztów, linkiem w każdej wiadomości.`,`3. Test „Która śmierć jest Twoja?” służy autorefleksji, działa w przeglądarce i nie wymaga podania danych.`,`4. Klient może w każdej chwili bez kosztów zrezygnować z Usługi bezpłatnej (np. wypisać się, usunąć Konto).`,`5. Sprzedawca może zakończyć świadczenie Usługi bezpłatnej z ważnej przyczyny (trwałe zakończenie usługi, rażące naruszenie Regulaminu) z 14-dniowym wypowiedzeniem przesłanym e-mailem. Nie wpływa to na dostęp do opłaconych Treści cyfrowych.`]},{id:`p6`,title:`§6. Konto`,body:[`1. Założenie Konta jest bezpłatne. Wymaga podania imienia, adresu e-mail i hasła albo logowania przez Google, potwierdzenia pełnoletności i akceptacji Regulaminu. Przy pierwszym zakupie Konto może powstać automatycznie — Klient otrzymuje wtedy e-mail z linkiem do ustawienia hasła.`,`2. Konto jest osobiste. Zabronione jest udostępnianie Konta i danych logowania innym osobom.`,`3. Klient może pobrać swoje dane i usunąć Konto w ustawieniach Konta. Usunięcie Konta kończy dostęp do Treści cyfrowych udostępnianych w Koncie, dlatego warto wcześniej pobrać pliki PDF i audio. Usunięcie Konta nie jest odstąpieniem od umowy i nie wpływa na uprawnienia z §14 i §15.`]},{id:`p7`,title:`§7. Zamówienia, ceny i płatności`,body:[`1. Informacje w Serwisie nie stanowią oferty w rozumieniu Kodeksu cywilnego, lecz zaproszenie do zawarcia umowy.`,`2. Ceny są podawane w złotych polskich i są cenami całkowitymi, które Klient płaci. Sprzedawca korzysta ze zwolnienia podmiotowego z podatku VAT (art. 113 ust. 1 ustawy o podatku od towarów i usług), dlatego ceny nie zawierają VAT. Nie ma kosztów dostawy ani innych opłat dodatkowych. Przy obniżce ceny Sprzedawca podaje także najniższą cenę z 30 dni przed wprowadzeniem obniżki.`,`3. Wiążąca jest cena widoczna w podsumowaniu Zamówienia w chwili jego złożenia. Kody rabatowe mają warunki podane przy ich udostępnieniu.`,`4. Aby złożyć Zamówienie, Klient wybiera produkt, podaje dane, akceptuje Regulamin, składa oświadczenia wymagane dla danego świadczenia (§9 ust. 2, §10 ust. 2) i klika przycisk „Zamawiam z obowiązkiem zapłaty”. Następnie zostaje przekierowany do płatności.`,`5. Umowa zostaje zawarta z chwilą zaksięgowania płatności. Nieopłacone Zamówienie nie prowadzi do zawarcia umowy i zostaje anulowane.`,`6. Płatności obsługuje PayU S.A. z siedzibą w Poznaniu (ul. Grunwaldzka 186, 60-166 Poznań). Dostępne są metody udostępnione przez PayU, w szczególności BLIK, szybkie przelewy internetowe i przelew bankowy — aktualna lista jest widoczna na stronie PayU przy płatności. Płatność jest jednorazowa i z góry, w terminie wskazanym na stronie PayU.`,`7. Po zawarciu umowy Klient otrzymuje e-mailem (trwały nośnik) potwierdzenie z treścią Regulaminu w wersji z dnia Zamówienia, złożonymi oświadczeniami i informacją o prawie odstąpienia od umowy albo jego utracie.`,`8. Dokument sprzedaży: na każdą sprzedaż Sprzedawca wystawia fakturę bez VAT (zwolnienie podmiotowe) i wysyła ją e-mailem. Dane do faktury można podać w Zamówieniu.`,`9. Serwis jest prowadzony w języku polskim, a sprzedaż odbywa się w złotych polskich. Treści cyfrowe, Karty podarunkowe i usługi online są dostępne bez ograniczeń terytorialnych, o ile prawo państwa Klienta nie zakazuje ich nabycia. Wydarzenia stacjonarne odbywają się w miejscu podanym w ich opisie.`]},{id:`p8`,title:`§8. Realizacja zamówienia i terminy`,body:[`1. Wszystkie świadczenia są dostarczane elektronicznie albo wykonywane osobiście — Sprzedawca nie wysyła przesyłek. Terminy liczy się od zaksięgowania płatności; przy tradycyjnym przelewie bankowym księgowanie trwa zwykle do 2 dni roboczych.`,`2. Treści cyfrowe — udostępniane w Koncie (zakładka „Moje produkty”), a niektóre pliki także e-mailem: zwykle w ciągu kilku minut, najpóźniej w ciągu 1 dnia roboczego.`,`3. Karta podarunkowa — kod wysyłany e-mailem: zwykle w ciągu kilku minut, najpóźniej w ciągu 1 dnia roboczego.`,`4. Bilet na Wydarzenie — e-mail z biletem i kodem QR albo z linkiem do Wydarzenia online: zwykle w ciągu kilku minut, najpóźniej w ciągu 1 dnia roboczego.`,`5. Sesja 1:1 — w terminie wybranym w kalendarzu rezerwacji; jeśli Klient nie wybrał terminu, Sprzedawca proponuje go w ciągu 3 dni roboczych.`,`6. Program POWRÓT — według harmonogramu określonego w umowie POWRÓT.`]},{id:`p9`,title:`§9. Treści cyfrowe i licencja`,body:[`1. Okres dostępu jest podany w opisie produktu przed zakupem, w potwierdzeniu Zamówienia i w Koncie. Jeśli opis nie mówi inaczej: pliki PDF i audio są dostępne bez ograniczenia czasu, dopóki Serwis działa, a filmy i kursy wideo — przez 12 miesięcy od zaksięgowania płatności. O zamknięciu Serwisu Sprzedawca uprzedzi e-mailem co najmniej 30 dni wcześniej, aby można było pobrać pliki.`,`2. Treści cyfrowe są dostarczane od razu po zakupie. Dlatego przed złożeniem Zamówienia Klient wyraża zgodę na dostarczenie Treści cyfrowej przed upływem terminu na odstąpienie od umowy i przyjmuje do wiadomości, że traci przez to prawo odstąpienia. Potwierdzenie tego oświadczenia trafia do e-maila, o którym mowa w §7 ust. 7.`,`3. Kurs wideo może być udostępniany stopniowo według harmonogramu podanego w opisie produktu.`,`4. Licencja: z chwilą dostarczenia Klient otrzymuje niewyłączną, niezbywalną licencję na korzystanie z Treści cyfrowych na własny użytek, na terytorium całego świata, w okresie dostępu, z prawem wydruku na własne potrzeby. Licencja nie obejmuje udostępniania Treści cyfrowych lub Konta innym osobom, rozpowszechniania, odsprzedaży, nagrywania filmów, usuwania oznaczeń licencji ani wykorzystania w celach komercyjnych — z zastrzeżeniem dozwolonego użytku osobistego.`,`5. Sprzedawca zapewnia aktualizacje potrzebne do zachowania zgodności Treści cyfrowej z umową przez okres dostępu i informuje o nich. Inne zmiany Treści cyfrowej są możliwe tylko na zasadach art. 43i ustawy o prawach konsumenta.`,`6. Przy rażącym lub powtarzającym się naruszeniu licencji Sprzedawca może, po bezskutecznym wezwaniu do zaprzestania naruszeń, wypowiedzieć umowę.`,`7. Prawa do Serwisu, nazwy i znaku „exmortis”, tekstów, nagrań, grafik i materiałów przysługują Sprzedawcy lub podmiotom, które udzieliły mu licencji.`]},{id:`p10`,title:`§10. Sesje 1:1`,body:[`1. Opis, czas trwania, forma (online przez Zoom albo na żywo) i cena sesji są podane na stronie produktu.`,`2. Jeśli sesja ma się odbyć przed upływem 14 dni od zawarcia umowy, Klient składa przy Zamówieniu żądanie rozpoczęcia usługi przed upływem tego terminu (§14 ust. 5).`,`3. Klient może bezpłatnie przełożyć albo odwołać sesję najpóźniej 24 godziny przed jej rozpoczęciem. Przy odwołaniu w tym terminie Klient wybiera zwrot ceny albo nowy termin.`,`4. Nieobecność bez uprzedzenia albo odwołanie później niż 24 godziny przed sesją oznacza wykorzystanie sesji, chyba że wynika z przyczyn niezależnych od Klienta (np. nagła choroba, awaria) — wtedy strony ustalają nowy termin.`,`5. Sprzedawca może przełożyć sesję z ważnej przyczyny, proponując nowy termin. Jeśli Klient go nie przyjmie, otrzymuje zwrot ceny tej sesji.`,`6. Sesje nie są nagrywane. Treść rozmów jest poufna, z wyjątkiem sytuacji bezpośredniego zagrożenia życia lub zdrowia oraz obowiązków wynikających z przepisów prawa.`,`7. Sprzedawca może odmówić sesji albo zaproponować jej przerwanie, jeśli uzna, że Klient potrzebuje najpierw pomocy specjalisty. Klient otrzymuje wtedy zwrot za niewykonaną część usługi.`]},{id:`p11`,title:`§11. Program POWRÓT`,body:[`1. Udział poprzedza zgłoszenie i bezpłatna rozmowa kwalifikacyjna. Ani zgłoszenie, ani rozmowa nie zobowiązują do zakupu.`,`2. Zakres, liczba i częstotliwość spotkań, czas trwania, cena i harmonogram są określone w umowie POWRÓT, przekazywanej Klientowi przed zapłatą. W sprawach nieuregulowanych umową stosuje się Regulamin.`,`3. Do przekładania spotkań i nieobecności stosuje się §10 ust. 3–5, chyba że umowa POWRÓT jest dla Klienta korzystniejsza.`,`4. Klient może zakończyć udział w programie w każdym czasie. Sprzedawca zwraca wtedy cenę spotkań, które się nie odbyły, liczoną proporcjonalnie do ceny całkowitej; przy płatności w ratach kolejne raty nie są należne. Prawo odstąpienia od umowy (§14) obowiązuje niezależnie.`,`5. Sprzedawca może zakończyć program z przyczyny wskazanej w §10 ust. 7 albo przy rażącym naruszeniu umowy, zwracając cenę niewykorzystanej części.`]},{id:`p12`,title:`§12. Wydarzenia i bilety`,body:[`1. Udział w Wydarzeniu wymaga zapisu (Wydarzenia bezpłatne) albo zakupu biletu (Wydarzenia płatne), chyba że opis stanowi inaczej. Link do Wydarzenia online i bilet z kodem QR są osobiste; bilet zawiera imię i nazwisko uczestnika.`,`2. Sprzedawca może odwołać albo przełożyć Wydarzenie, informując zapisanych e-mailem. Przy płatnym Wydarzeniu Klient wybiera nowy termin albo zwrot ceny.`,`3. Uczestnik może mieć wyłączoną kamerę i mikrofon. Wydarzenia z udziałem uczestników nie są nagrywane (§18).`,`4. Zabronione jest nagrywanie Wydarzeń przez uczestników, zakłócanie ich przebiegu i publikowanie treści obraźliwych lub bezprawnych. Osoba naruszająca te zasady może zostać usunięta z Wydarzenia.`]},{id:`p13`,title:`§13. Karty podarunkowe`,body:[`1. Karta podarunkowa to jednorazowy kod o wartości wybranej przy zakupie, do wykorzystania na produkty w Skarbcu. Kod przychodzi e-mailem razem z kartą do przekazania obdarowanemu.`,`2. Kod jest ważny 6 miesięcy od dnia zakupu; data ważności jest podana na karcie i w e-mailu. Po tym terminie kodu nie można wykorzystać.`,`3. Kod wykorzystuje się jednorazowo, wpisując go w kasie. Jeżeli wartość Zamówienia jest niższa niż wartość karty, niewykorzystana różnica nie jest wypłacana ani przenoszona na kolejne zakupy.`,`4. Karty podarunkowej nie można wymienić na gotówkę. Konsument, który kupił kartę, może odstąpić od umowy w terminie 14 dni od zakupu, jeżeli kod nie został wykorzystany.`]},{id:`p14`,title:`§14. Prawo odstąpienia od umowy i zwroty`,body:[`1. Konsument może odstąpić od umowy zawartej na odległość w terminie 14 dni od dnia jej zawarcia, bez podania przyczyny i bez ponoszenia kosztów, z zastrzeżeniem ust. 4–5.`,`2. Aby odstąpić, wystarczy przed upływem terminu wysłać oświadczenie: formularzem „Odstąp od umowy tutaj” na stronie exmortis.pl/odstapienie, e-mailem na [E-MAIL KONTAKTOWY] albo pocztą na [ADRES DO KORESPONDENCJI]. Można skorzystać ze wzoru formularza (Załącznik nr 1), ale nie jest to obowiązkowe.`,`3. Sprzedawca niezwłocznie potwierdza e-mailem otrzymanie oświadczenia, z datą i godziną jego wpływu, i zwraca wszystkie płatności w ciągu 14 dni od jego otrzymania, tym samym sposobem płatności, którego użył Konsument, chyba że Konsument zgodzi się na inny sposób niewiążący się dla niego z kosztami. Sprzedawca nie sprzedaje rzeczy, więc Konsument niczego nie odsyła i nie ponosi kosztów zwrotu.`,`4. TREŚCI CYFROWE — prawo odstąpienia nie przysługuje, jeżeli Sprzedawca rozpoczął dostarczanie Treści cyfrowych za wyraźną i uprzednią zgodą Konsumenta, który został poinformowany przed rozpoczęciem świadczenia, że po jego spełnieniu utraci prawo odstąpienia, przyjął to do wiadomości, a Sprzedawca przekazał mu potwierdzenie (art. 38 ust. 1 pkt 13 ustawy o prawach konsumenta). Powodem jest to, że dostarczonej treści cyfrowej nie da się zwrócić.`,`5. SESJE 1:1, PROGRAM POWRÓT I PŁATNE WYDARZENIA ONLINE — jeżeli Konsument zażądał rozpoczęcia usługi przed upływem terminu na odstąpienie, a następnie odstąpi od umowy, płaci za świadczenia spełnione do chwili odstąpienia, proporcjonalnie do ceny całkowitej (art. 35 ustawy o prawach konsumenta). Prawo odstąpienia nie przysługuje po pełnym wykonaniu usługi, jeżeli Sprzedawca wykonał ją za wyraźną i uprzednią zgodą Konsumenta, który został poinformowany, że po jej spełnieniu utraci prawo odstąpienia, i przyjął to do wiadomości (art. 38 ust. 1 pkt 1).`,`6. Bez żądania, o którym mowa w ust. 5, usługa zaczyna się po upływie 14 dni od zawarcia umowy.`,`7. Odstąpienie od umowy, reklamacja i ewentualna dobrowolna gwarancja zwrotu to odrębne uprawnienia; skorzystanie z jednego nie ogranicza pozostałych.`]},{id:`p15`,title:`§15. Zgodność z umową i reklamacje`,body:[`1. Sprzedawca odpowiada wobec Konsumenta i PNPK za zgodność Treści cyfrowych z umową na zasadach rozdziału 5b ustawy o prawach konsumenta, a za usługi — na zasadach Kodeksu cywilnego.`,`2. Przy braku zgodności Treści cyfrowej z umową Klient może żądać doprowadzenia do zgodności (np. poprawionego pliku, przywrócenia dostępu), a gdy nie jest to możliwe, nie nastąpiło w rozsądnym czasie albo brak zgodności jest istotny — obniżenia ceny albo odstąpienia od umowy.`,`3. Reklamację można złożyć formularzem na stronie Kontakt, e-mailem na [E-MAIL KONTAKTOWY] albo pocztą na [ADRES DO KORESPONDENCJI]. Warto opisać problem, podać numer zamówienia i swoje żądanie — brak tych informacji nie powoduje odrzucenia reklamacji.`,`4. Sprzedawca odpowiada na reklamację w ciągu 14 dni od jej otrzymania, e-mailem albo na piśmie. Brak odpowiedzi w tym terminie oznacza uznanie reklamacji (art. 7a ustawy o prawach konsumenta).`]},{id:`p16`,title:`§16. Gwarancja i pomoc po zakupie`,body:[`1. Sprzedawca nie udziela gwarancji handlowej. Jeżeli opis produktu albo umowa POWRÓT przewiduje dobrowolną gwarancję zwrotu, jej warunki są podane przed zakupem i nie ograniczają uprawnień z §14 i §15.`,`2. Pomoc w sprawach technicznych (dostęp, pobieranie, odtwarzanie) jest bezpłatna: e-mail [E-MAIL KONTAKTOWY] albo formularz Kontakt. Sprzedawca odpowiada zwykle w ciągu 2 dni roboczych.`]},{id:`p17`,title:`§17. Opinie i treści użytkowników`,body:[`1. Opinię o produkcie może dodać tylko osoba, która kupiła ten produkt w Serwisie — system sprawdza to na podstawie opłaconego zamówienia przypisanego do Konta. Każda opinia jest przeglądana przed publikacją. Publikowane są opinie pozytywne i negatywne; Sprzedawca nie płaci za opinie.`,`2. Sprzedawca nie publikuje albo usuwa opinie bezprawne, obraźliwe, ujawniające dane osób trzecich, niezwiązane z produktem lub będące reklamą. O odmowie publikacji albo usunięciu informuje autora e-mailem, podając przyczynę; autor może odpowiedzieć na tę decyzję e-mailem.`,`3. Treści bezprawne w Serwisie można zgłosić na [E-MAIL KONTAKTOWY], wskazując adres strony, opis treści i uzasadnienie. Ten adres jest także punktem kontaktowym dla organów i użytkowników w rozumieniu art. 11 i 12 aktu o usługach cyfrowych (rozporządzenie (UE) 2022/2065); kontakt w języku polskim lub angielskim.`]},{id:`p18`,title:`§18. Nagrywanie i publikacja`,body:[`1. Wydarzenia z udziałem uczestników, sesje 1:1 i spotkania programu POWRÓT nie są nagrywane.`,`2. Nagrywane mogą być wyłącznie spotkania, transmisje i odcinki podcastu, w których występuje sam prowadzący albo prowadzący i zaproszony gość. Informacja o nagraniu jest podana na stronie takiego spotkania.`,`3. Nagranie z udziałem gościa wymaga odrębnej umowy albo pisemnej zgody gościa, określającej zakres, miejsce i czas publikacji, formę wystąpienia (z imieniem, pseudonimem lub anonimowo) oraz możliwość zatwierdzenia materiału przed publikacją.`]},{id:`p19`,title:`§19. Przedsiębiorcy na prawach konsumenta`,body:[`1. Postanowienia o odstąpieniu od umowy (§14) i o zgodności Treści cyfrowych z umową (§15) stosuje się do PNPK (art. 7aa ustawy o prawach konsumenta). PNPK może oświadczyć przy Zamówieniu albo e-mailem, że umowa nie ma dla niej charakteru zawodowego; złożenie takiego oświadczenia nie jest warunkiem zakupu.`,`2. Wobec Klientów niebędących Konsumentami ani PNPK odpowiedzialność Sprzedawcy jest ograniczona do wysokości zapłaconej ceny, z wyjątkiem szkody wyrządzonej umyślnie.`]},{id:`p20`,title:`§20. Pozasądowe rozwiązywanie sporów`,body:[`Konsument może skorzystać z pomocy miejskiego lub powiatowego rzecznika konsumentów, organizacji konsumenckich, stałego polubownego sądu konsumenckiego przy wojewódzkim inspektorze Inspekcji Handlowej oraz z mediacji. Informacje: uokik.gov.pl. Udział Sprzedawcy w takim postępowaniu jest dobrowolny.`]},{id:`p21`,title:`§21. Dane osobowe`,body:[`Zasady przetwarzania danych osobowych opisuje Polityka prywatności (exmortis.pl/polityka-prywatnosci), a zasady plików cookies — Polityka cookies.`]},{id:`p22`,title:`§22. Zmiany Regulaminu`,body:[`1. Sprzedawca może zmienić Regulamin z ważnych przyczyn: zmiany przepisów prawa, orzeczeń lub decyzji organów, zmiany zakresu lub sposobu świadczenia usług, zmiany metod płatności, konieczności zapewnienia bezpieczeństwa lub przeciwdziałania nadużyciom albo zmian redakcyjnych.`,`2. Posiadacze Kont i subskrybenci są informowani o zmianie e-mailem co najmniej 14 dni przed jej wejściem w życie. Kto nie akceptuje zmian, może przed tą datą bez kosztów zrezygnować z Usług bezpłatnych.`,`3. Do umów zawartych przed zmianą stosuje się Regulamin w brzmieniu z dnia zawarcia umowy.`]},{id:`p23`,title:`§23. Postanowienia końcowe`,body:[`1. Regulamin podlega prawu polskiemu. Wybór prawa nie pozbawia Konsumenta ochrony przysługującej mu na podstawie bezwzględnie obowiązujących przepisów państwa jego zwykłego pobytu.`,`2. Postanowienia Regulaminu nie wyłączają ani nie ograniczają praw Konsumentów i PNPK wynikających z bezwzględnie obowiązujących przepisów.`,`3. Regulamin w tym brzmieniu obowiązuje od 10 listopada 2026 r. dla umów zawieranych od tego dnia. Wobec osób, które przed tym dniem założyły Konto lub zapisały się na newsletter, w zakresie Usług bezpłatnych obowiązuje od 24 listopada 2026 r. (po 14-dniowym powiadomieniu); do tego czasu stosuje się wobec nich poprzednią wersję, dostępną w części „Poprzednie wersje”.`]}]},c={id:`zalacznik-1`,title:`Załącznik nr 1 — Wzór formularza odstąpienia od umowy`,body:[`(formularz należy wypełnić i odesłać tylko w przypadku chęci odstąpienia od umowy)`,`Adresat: [NAZWA FIRMY], [ADRES DO KORESPONDENCJI], e-mail: [E-MAIL KONTAKTOWY]`,`Ja/My(*) niniejszym informuję/informujemy(*) o moim/naszym(*) odstąpieniu od umowy o dostarczenie następujących treści cyfrowych(*) / o świadczenie następującej usługi(*): ………………………………………`,`Data zawarcia umowy: ………………`,`Numer zamówienia (jeśli znany): ………………`,`Imię i nazwisko konsumenta(-ów): ………………`,`Adres konsumenta(-ów): ………………`,`Adres e-mail użyty przy zamówieniu: ………………`,`Podpis konsumenta(-ów) (tylko jeżeli formularz jest przesyłany w wersji papierowej): ………………`,`Data: ………………`,`(*) Niepotrzebne skreślić.`]},l={title:`Polityka prywatności exmortis.pl`,version:`1.4`,sections:[{id:`p1`,title:`§1. Administrator`,body:[`1. Administratorem Twoich danych osobowych jest [IMIĘ I NAZWISKO], przedsiębiorca prowadzący działalność gospodarczą pod firmą [NAZWA FIRMY], adres: [ADRES DZIAŁALNOŚCI], NIP: [NIP] (dalej: „Administrator”, „my”).`,`2. Kontakt w sprawach danych osobowych: [E-MAIL KONTAKTOWY] lub pocztą na [ADRES DO KORESPONDENCJI]. Nie wyznaczyliśmy inspektora ochrony danych.`]},{id:`p2`,title:`§2. Najważniejsze zasady`,body:[`Zbieramy tylko dane, których potrzebujemy. Nie sprzedajemy danych. Nie wysyłamy reklam bez Twojej zgody. Test „Która śmierć jest Twoja?” jest narzędziem refleksji, a nie diagnozą — nie zbiera danych o zdrowiu. Odpowiedzi w ankietach mentoringowych i treść rozmów mogą dotyczyć zdrowia lub przekonań — przetwarzamy je wyłącznie za Twoją wyraźną zgodą i nigdy nie przekazujemy do celów reklamowych.`]},{id:`p3`,title:`§3. Cele, podstawy prawne i okres przechowywania`,body:[`1. Konto w Serwisie — imię, e-mail, hasło (zaszyfrowane), ustawienia, urządzenia. Podstawa: wykonanie umowy o prowadzenie Konta (art. 6 ust. 1 lit. b RODO). Okres: do usunięcia Konta.`,`2. Sprzedaż Treści cyfrowych i usług — dane z Zamówienia (imię, e-mail, dane do faktury, produkt, kwota, zgody). Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b), a w zakresie rozliczeń — obowiązek prawny (art. 6 ust. 1 lit. c RODO, przepisy podatkowe i o rachunkowości). Okres: przez czas trwania umowy i dostępu, a dane rozliczeniowe — 5 lat od końca roku kalendarzowego, w którym upłynął termin płatności podatku.`,`3. Reklamacje, odstąpienia, obsługa korespondencji — Podstawa: obowiązek prawny (art. 6 ust. 1 lit. c) oraz nasz prawnie uzasadniony interes w odpowiadaniu na wiadomości (art. 6 ust. 1 lit. f). Okres: do zakończenia sprawy, a następnie do upływu terminu przedawnienia roszczeń.`,`4. Newsletter „Listy powrotu” — e-mail, imię, data i treść zgody, informacja o otwarciach i kliknięciach, źródło zapisu. Podstawa: Twoja zgoda (art. 6 ust. 1 lit. a RODO) oraz zgoda na otrzymywanie informacji handlowych e-mailem (art. 398 Prawa komunikacji elektronicznej). Zapis staje się aktywny dopiero po kliknięciu linku potwierdzającego, który wysyłamy e-mailem; datę kliknięcia zapisujemy jako datę zgody. Okres: do wycofania zgody (wypisania się); niepotwierdzone zapisy usuwamy po 7 dniach.`,`5. Test „Która śmierć jest Twoja?” — służy autorefleksji; nie jest narzędziem diagnostycznym ani oceną stanu zdrowia. Test działa wyłącznie w Twojej przeglądarce: odpowiedzi, punkty, wynik i wybrany etap są przetwarzane tylko w pamięci otwartej strony i znikają po jej odświeżeniu lub zamknięciu. Nie zapisujemy ich w bazie, nie wysyłamy e-mailem i nie przekazujemy do narzędzi analitycznych ani reklamowych — na stronie testu te narzędzia są wyłączone także po wyrażeniu zgody w banerze cookies. Do wykonania testu nie potrzebujesz konta ani adresu e-mail. Na serwer trafia wyłącznie nazwa wyniku, do anonimowego licznika: zapisujemy tylko dzienną liczbę ukończeń testu w podziale na nazwę wyniku (np. „duchowa: 3”) — bez odpowiedzi, etapu, konta, adresu e-mail, adresu IP i identyfikatorów; z tych sum nie da się ustalić, kto wypełnił test, więc nie są danymi osobowymi. Jak przy każdej stronie, dostawca hostingu może zapisać techniczny log wejścia (np. adres IP, czas, adres strony) — bez odpowiedzi i wyniku testu. Wyniki zapisane przed 4.11.2026 (anonimowe sumy punktów i kategorie) przechowujemy do czasu ich usunięcia zgodnie z dotychczasowym okresem — nie dłużej niż 12 miesięcy od zapisu.`,`6. Bezpłatne materiały (PDF) — imię i e-mail. Podstawa: wykonanie umowy o dostarczenie materiału (art. 6 ust. 1 lit. b RODO). Okres: do wysyłki materiału i rozpatrzenia ewentualnych reklamacji; jeśli zapiszesz się też na Listy powrotu — jak w ust. 4.`,`7. Spotkania online i stacjonarne (webinary, „Wieczory powrotu”) — imię, e-mail, obecność, źródło zapisu; przy Spotkaniach stacjonarnych — imię i nazwisko na bilecie z kodem QR. Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b). Spotkania nie są nagrywane. Okres: 90 dni po Spotkaniu, potem dane usuwamy automatycznie.`,`8. Usługi mentoringowe (Rozmowa na progu, POWRÓT) i formularze kwalifikacyjne — dane kontaktowe, terminy, notatki ze spotkań, informacje, które przekażesz, w tym dotyczące zdrowia, samopoczucia, przekonań religijnych lub światopoglądowych i życia rodzinnego. Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b) oraz Twoja wyraźna zgoda na dane szczególnych kategorii (art. 9 ust. 2 lit. a RODO). W sytuacji bezpośredniego zagrożenia życia — ochrona żywotnych interesów (art. 6 ust. 1 lit. d i art. 9 ust. 2 lit. c RODO), np. przekazanie służbom informacji o Twojej lokalizacji. Okres: zgłoszenie, po którym nie rozpoczęliśmy współpracy — 6 miesięcy od jego wysłania; po rozpoczęciu współpracy — do jej zakończenia i 12 miesięcy po niej (kontynuacja i sesje kontrolne), a następnie dane i notatki usuwamy; dane rozliczeniowe — jak w ust. 2.`,`9. Bezpieczeństwo Serwisu i ochrona Treści cyfrowych — adres IP, dane urządzenia i przeglądarki, dziennik logowań i odtworzeń, identyfikator licencji, znak wodny z e-mailem na filmach i w plikach PDF, limit urządzeń. Podstawa: nasz prawnie uzasadniony interes w zapewnieniu bezpieczeństwa i ochronie praw autorskich (art. 6 ust. 1 lit. f). Okres: dzienniki — 90 dni; identyfikator licencji powiązany z Zamówieniem — jak dane Zamówienia.`,`10. Ustalenie, dochodzenie i obrona roszczeń — Podstawa: prawnie uzasadniony interes (art. 6 ust. 1 lit. f). Okres: do upływu terminów przedawnienia.`,`11. Statystyka i marketing (pliki cookies, piksel Meta) — wyłącznie po Twojej zgodzie w panelu cookies (art. 6 ust. 1 lit. a RODO). Szczegóły w Polityce cookies. W zakresie zbierania i przekazywania danych przez piksel Meta jesteśmy współadministratorem z Meta Platforms Ireland Ltd.; dalsze przetwarzanie przez Meta odbywa się na zasadach Meta.`,`12. Profile w mediach społecznościowych (Facebook, Instagram, WhatsApp) — dane osób, które z nami wchodzą w interakcję (komentarze, wiadomości, statystyki). Podstawa: prawnie uzasadniony interes w prowadzeniu komunikacji (art. 6 ust. 1 lit. f). W zakresie statystyk stron jesteśmy współadministratorem z Meta Platforms Ireland Ltd. Okres: do usunięcia treści lub zgłoszenia sprzeciwu.`,`13. Adres IP przy zapisach i wiadomościach (zapisy na Spotkania, formularz kontaktowy i inne formularze) — ochrona przed nadużyciami i spamem (np. limit zapisów z jednego adresu). Podstawa: nasz prawnie uzasadniony interes (art. 6 ust. 1 lit. f RODO). Okres: adres IP przechowujemy w dzienniku bezpieczeństwa 90 dni.`,`14. Rezerwacje sesji 1:1 — imię, e-mail, termin oraz informacje, które przekażesz przy rezerwacji; jeśli dotyczą zdrowia — wyłącznie za Twoją osobną zgodą (art. 9 ust. 2 lit. a RODO). Termin sesji z rodzajem spotkania i imieniem zapisujemy w kalendarzu Google. Podstawa: wykonanie umowy (art. 6 ust. 1 lit. b).`,`15. Zgłoszenia do podcastu — imię, e-mail, telefon, Twoja historia, wybrana forma publikacji, profile w mediach społecznościowych. Historia może dotyczyć zdrowia lub przekonań, dlatego podstawą jest Twoja wyraźna zgoda (art. 9 ust. 2 lit. a RODO). Zgłoszenia, które nie zakończą się nagraniem, usuwamy automatycznie po 6 miesiącach. Nagranie i publikacja wymagają Twojej osobnej, podpisanej zgody.`,`16. Opinie o produktach i powiadomienia o dostępności — przy opinii: podpis, ocena, treść i powiązanie z zakupem (podpis i treść są publiczne); przy powiadomieniu: e-mail i produkt. Podstawa: umowa o usługę elektroniczną (art. 6 ust. 1 lit. b).`,`17. Kopie zapasowe — raz w tygodniu tworzymy kopię danych (bez haseł i kluczy), dostępną tylko dla Administratora; przechowujemy 8 ostatnich kopii. Dane usunięte z Serwisu znikają z kopii najpóźniej po około 8 tygodniach.`]},{id:`p4`,title:`§4. Czy musisz podać dane?`,body:[`Podanie danych jest dobrowolne, ale bez nich nie założysz Konta, nie złożysz Zamówienia, nie zapiszesz się na Wydarzenie ani nie otrzymasz newslettera. Dane rozliczeniowe są wymagane przepisami podatkowymi.`]},{id:`p5`,title:`§5. Zautomatyzowane decyzje`,body:[`Nie podejmujemy wobec Ciebie decyzji wywołujących skutki prawne wyłącznie w sposób zautomatyzowany. System bezpieczeństwa może automatycznie wstrzymać odtwarzanie wideo na 24 godziny przy podejrzeniu udostępniania Konta — możesz się od tego odwołać, a dalszą decyzję zawsze podejmuje człowiek.`]},{id:`p6`,title:`§6. Odbiorcy danych`,body:[`Twoje dane mogą otrzymać podmioty, które przetwarzają je w naszym imieniu na podstawie umów powierzenia, wyłącznie w zakresie potrzebnym do świadczenia usług:`,`- hosting i platforma Serwisu, w tym analityka odwiedzin (wyłącznie po Twojej zgodzie na cookies analityczne): Base44, Inc. — dostawca platformy, na której działa Serwis (podmiot przetwarzający dane na podstawie umowy powierzenia: base44.com/dpa). Przekazanie danych poza EOG: EU-US Data Privacy Framework albo standardowe klauzule umowne UE;`,`- Supabase, Inc. — dostawca bazy danych (serwery w UE, Frankfurt), podmiot przetwarzający na podstawie umowy powierzenia;`,`- hosting strony exmortis.pl: cyberfolks;`,`- operator płatności: [OPERATOR PŁATNOŚCI], [ADRES OPERATORA] — w zakresie płatności jest odrębnym administratorem;`,`- wystawianie faktur: Fakturownia;`,`- system mailingowy: [NAZWA, np. MailerLite];`,`- wideokonferencje: Zoom Video Communications, Inc. (USA);`,`- poczta e-mail: [DOSTAWCA POCZTY];`,`- logowanie przez Google (jeśli z niego korzystasz): Google Ireland Ltd.; kalendarz terminów sesji 1:1: Google;`,`- odtwarzacze YouTube (Google) i Spotify — ładują się dopiero po Twoim kliknięciu albo zgodzie w panelu cookies; ich dostawcy są odrębnymi administratorami;`,`- Meta Platforms Ireland Ltd. — w zakresie opisanym w §3 ust. 11–12;`,`- biuro rachunkowe: [NAZWA]; kancelaria prawna — w razie potrzeby;`,`- organy publiczne — wyłącznie gdy wymagają tego przepisy.`]},{id:`p7`,title:`§7. Przekazywanie danych poza Europejski Obszar Gospodarczy`,body:[`Niektórzy dostawcy (np. Zoom, Meta, Google, Base44, Inc.) mogą przetwarzać dane poza EOG, w tym w USA lub w Izraelu. Odbywa się to na podstawie decyzji Komisji Europejskiej stwierdzającej odpowiedni stopień ochrony (np. EU–US Data Privacy Framework dla certyfikowanych podmiotów, decyzja dotycząca Izraela) albo standardowych klauzul umownych zatwierdzonych przez Komisję. Kopię zabezpieczeń możesz uzyskać, pisząc do nas.`,`Supabase, Inc. ma siedzibę w USA. Dane w bazie przechowujemy na serwerach w UE (Frankfurt), a ewentualne przekazanie danych do Supabase, Inc. w USA odbywa się na podstawie standardowych klauzul umownych UE lub EU–US Data Privacy Framework.`]},{id:`p8`,title:`§8. Twoje prawa`,body:[`Masz prawo do: dostępu do danych i otrzymania ich kopii, sprostowania, usunięcia, ograniczenia przetwarzania, przenoszenia danych, sprzeciwu wobec przetwarzania opartego na prawnie uzasadnionym interesie (a wobec marketingu — w każdej chwili), wycofania zgody w dowolnym momencie (bez wpływu na zgodność z prawem przetwarzania przed wycofaniem). Część praw zrealizujesz samodzielnie w Koncie („Pobierz moje dane”, „Usuń konto”, zgody). Odpowiadamy w ciągu miesiąca. Masz też prawo wnieść skargę do Prezesa Urzędu Ochrony Danych Osobowych (ul. Stawki 2, 00-193 Warszawa, uodo.gov.pl).`]},{id:`p9`,title:`§9. Bezpieczeństwo`,body:[`Stosujemy szyfrowane połączenie (HTTPS), szyfrowanie haseł, kontrolę dostępu, weryfikację dwuetapową dla administratora, dzienniki bezpieczeństwa i ograniczony dostęp do danych. Do treści rozmów mentoringowych dostęp ma wyłącznie prowadzący (Administrator).`]},{id:`p10`,title:`§10. Osoby niepełnoletnie`,body:[`Serwis i usługi są przeznaczone dla osób pełnoletnich. Nie zbieramy świadomie danych osób poniżej 18. roku życia — jeśli dowiemy się o takich danych, usuniemy je.`]},{id:`p11`,title:`§11. Zmiany Polityki`,body:[`O istotnych zmianach poinformujemy na stronie i e-mailem posiadaczy Kont. Poprzednie wersje są dostępne w archiwum.`]}]},u={regulamin:{doc:s,extra:[c]},prywatnosc:{doc:l,extra:[]},cookies:{doc:t,extra:[]}};function d(t,r={},a={},o=null,s=[]){let{doc:c,extra:l}=u[t]||{doc:o||{title:``,sections:[]},extra:s||[]},d=e=>i(n(e,r),a);return{title:c.title,sections:[...c.sections,...l].map(t=>({id:t.id,title:t.title,body:t.body.map(d).filter(Boolean),...t.table?{table:e.map(e=>e.map(d))}:{}}))}}var f=(e,t)=>Object.fromEntries(Object.keys(u).map(n=>[n,d(n,e,t)]));export{c as a,s as i,d as n,a as o,l as r,o as s,f as t};